SELECT CASE WHEN p.stock_qty >= 447 THEN 'high' WHEN p.stock_qty >= 95 THEN 'mid' ELSE 'low' END AS stock_qty_bucket, DATE_FORMAT(p.launch_date, 'yyyy-MM') AS launch_month, AVG(oi.unit_price) AS avg_unit_price FROM order_items oi INNER JOIN products p ON oi.product_id = p.id LEFT OUTER JOIN orders o ON oi.order_id = o.id GROUP BY CASE WHEN p.stock_qty >= 447 THEN 'high' WHEN p.stock_qty >= 95 THEN 'mid' ELSE 'low' END, DATE_FORMAT(p.launch_date, 'yyyy-MM') ORDER BY launch_month
